ALTER TABLE quiz_tasks ADD COLUMN hint_example TEXT NULL AFTER hint_rule;
ALTER TABLE order_tasks ADD COLUMN hint_example TEXT NULL AFTER hint_rule;
ALTER TABLE find_error_tasks ADD COLUMN hint_example TEXT NULL AFTER hint_rule;
ALTER TABLE graph_tasks ADD COLUMN hint_example TEXT NULL AFTER hint_rule;
ALTER TABLE matching_tasks ADD COLUMN hint_example TEXT NULL AFTER hint_rule;
ALTER TABLE blank_tasks ADD COLUMN hint_example TEXT NULL AFTER hint_rule;

UPDATE order_tasks SET hint_example = CASE id
 WHEN 1 THEN 'Інші дані: $2z+7=25$. Віднімаємо 7: $2z=18$. Ділимо на 2: $z=9$. Перевірка: $2·9+7=25$.'
 WHEN 2 THEN 'Інші дані: $3(z-2)=21$. Розкриваємо дужки: $3z-6=21$, тоді $3z=27$, $z=9$. Перевірка: $3·(9-2)=21$.'
 WHEN 3 THEN 'Інші дані: $z^2-13z+42=0$. Числа -6 і -7 мають суму -13 та добуток 42. Отже, $(z-6)(z-7)=0$, звідки $z=6$ або $z=7$.'
 WHEN 4 THEN 'Інші дані: $5z-2=43$. Додаємо 2: $5z=45$. Ділимо на 5: $z=9$. Перевірка: $5·9-2=43$.' END WHERE id BETWEEN 1 AND 4;
UPDATE find_error_tasks SET hint_example = CASE id
 WHEN 1 THEN 'Інші дані: $7z-8=3z+20$. Запис $7z-3z=20-8$ помилковий: треба додати 8 до обох частин. Правильно $4z=28$, $z=7$; обидві початкові частини дорівнюють 41.'
 WHEN 2 THEN 'Інші дані: $(z+5)^2=(z+5)(z+5)=z^2+5z+5z+25=z^2+10z+25$. Запис $z^2+25$ пропускає два перехресні добутки.'
 WHEN 3 THEN 'Інші дані: 200 грн знижують на 10%, потім підвищують на 10%. Маємо $200·0{,}9=180$, потім $180·1{,}1=198$ грн. Додавати 20 грн на другому кроці помилково: нова база — 180 грн.'
 WHEN 4 THEN 'Інші дані: $6z-9=2z+19$. Правильно $6z-2z=19+9$, тоді $4z=28$, $z=7$. Перевірка: $42-9=14+19=33$.' END WHERE id BETWEEN 1 AND 4;
UPDATE graph_tasks SET hint_example = CASE id
 WHEN 1 THEN 'Інша функція: $y=3z+2$. Точка $P(2;8)$ належить графіку, бо $3·2+2=8$. Точка $Q(2;7)$ не належить, бо $8≠7$.'
 WHEN 2 THEN 'Інша функція: $y=z^2+2$. Для $P(-3;11)$ маємо $(-3)^2+2=11$, отже точка належить графіку. Для $Q(3;10)$ отримуємо 11, а не 10.'
 WHEN 3 THEN 'Інше рівняння: $z^2-13z+42=0$. Розкладаємо: $(z-6)(z-7)=0$. На числовій прямій обираємо координати 6 і 7; при $z=5$ ліва частина дорівнює 2, тому цю точку не обираємо.'
 WHEN 4 THEN 'Інша функція: $y=-2z+7$. Точка $P(3;1)$ підходить: $-2·3+7=1$. Точка $Q(3;2)$ не підходить: значення функції дорівнює 1.' END WHERE id BETWEEN 1 AND 4;
UPDATE matching_tasks SET hint_example = CASE id
 WHEN 1 THEN 'Інші вирази: $z^2-49=(z-7)(z+7)$, $z^2+14z+49=(z+7)^2$, $z^2-12z+36=(z-6)^2$. Розкриття дужок підтверджує кожну пару.'
 WHEN 2 THEN 'Інші кути: суміжний із 35° дорівнює $180°-35°=145°$; вертикальний до 65° дорівнює 65°. Спочатку визначаємо вид зв’язку, потім знаходимо величину.'
 WHEN 3 THEN 'Інші відсотки: збільшення на 12% відповідає множнику $1+0{,}12=1{,}12$, зменшення на 12% — $1-0{,}12=0{,}88$. Наприклад, 200 перетворюється на 224 або 176.'
 WHEN 4 THEN 'Інші вирази: $z^2-64=(z-8)(z+8)$, $z^2+16z+64=(z+8)^2$, $z^2-18z+81=(z-9)^2$. Перевіряємо пари множенням дужок.' END WHERE id BETWEEN 1 AND 4;
UPDATE blank_tasks SET hint_example = CASE id
 WHEN 1 THEN 'Інші дані: $5z+9=54$. Послідовні значення: віднімаємо 9, отримуємо $5z=45$, ділимо на 5 й отримуємо $z=9$. Перевірка: $45+9=54$.'
 WHEN 2 THEN 'Інші дані: 12% від 400. Перетворюємо відсотки на дріб: $12:100=0{,}12$. Обчислюємо $400·0{,}12=48$.'
 WHEN 3 THEN 'Інші дані: $z^2-13z+42=0$. $a=1$, $b=-13$, $c=42$; $D=169-168=1$. Корені $(13+1):2=7$ і $(13-1):2=6$. Їхня сума 13, добуток 42.'
 WHEN 4 THEN 'Інші дані: $2z-7=11$. Додаємо 7: $2z=18$, ділимо на 2: $z=9$. Перевірка: $18-7=11$.' END WHERE id BETWEEN 1 AND 4;

UPDATE find_error_tasks SET hint_rule = 'Додавайте або віднімайте однаковий вираз з обох частин рівняння; при перенесенні доданка його знак змінюється.' WHERE id IN (1,4);
UPDATE find_error_tasks SET hint_rule = 'Квадрат суми дорівнює сумі квадратів доданків і подвоєного їхнього добутку: $(a+b)^2=a^2+2ab+b^2$.' WHERE id=2;
UPDATE find_error_tasks SET hint_rule = 'Послідовно множте поточну ціну на $1-p/100$ при зниженні та на $1+p/100$ при підвищенні. База другого відсотка — результат першої зміни.' WHERE id=3;
UPDATE graph_tasks SET hint_rule = 'Для $(x-a)(x-b)=0$ хоча б один множник дорівнює нулю. Знайдіть a і b за коефіцієнтами, потім перевірте координати підстановкою.' WHERE id=3;
UPDATE blank_tasks SET hint_rule = 'Відсоток p переводиться у дріб p/100. Щоб знайти p відсотків від числа N, обчисліть N·p/100.' WHERE id=2;
UPDATE blank_tasks SET hint_rule = 'Для квадратного рівняння визначте a, b, c зі знаками. Обчисліть D=b²-4ac, потім корені (-b±√D)/(2a), якщо D≥0 та a≠0.' WHERE id=3;
